#!/usr/bin/env node
/**
 * Sprint F1 — custom domain setup guide generator
 */
import { writeFileSync, mkdirSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
export const DOMAIN_GUIDE_PATH = join(ROOT, 'master-vault', 'DOMAIN-SETUP-GUIDE.md');

export function buildDomainSetupGuide() {
  return [
    '# LeaseSmart Domain Setup Guide',
    '',
    '**TGT Technologies Inc.** — how `leasesmart.tgttechnologies.com` is actually served, and how to verify it.',
    '',
    '> Generated by `scripts/domain-setup-guide.mjs`.',
    '',
    '## Overview — what serves the live site',
    '',
    'The live beta is served by **Netlify**, not GitHub Pages. The subdomain is a',
    '**CNAME** to a Netlify site, while the `tgttechnologies.com` apex sits behind Cloudflare.',
    '',
    '| Host | DNS | Serves |',
    '|------|-----|--------|',
    '| `leasesmart.tgttechnologies.com` | CNAME → `leasesmart2.netlify.app` | LeaseSmart beta (Netlify) |',
    '| `tgttechnologies.com` | Cloudflare | TGT corporate site |',
    '| `troythompson70-cpu.github.io/leasesmart` | GitHub Pages | Same build, parallel deploy |',
    '',
    '## Two deploy paths are live at once',
    '',
    'Pushing to `main` triggers `.github/workflows/pages.yml`, which generates `config.js`',
    'from repo secrets and publishes to GitHub Pages. Netlify builds the same repo and is',
    'what the custom domain resolves to. Both currently serve identical output, so a change',
    'is only live on the custom domain once **Netlify** has finished — a green Pages workflow',
    'is not proof the custom domain updated.',
    '',
    '## Step 1 — DNS for the subdomain',
    '',
    '1. Open DNS for `tgttechnologies.com` at whichever provider hosts the zone.',
    '2. Confirm or add a **CNAME** record:',
    '   - **Type:** CNAME',
    '   - **Name / Host:** `leasesmart` (subdomain only — not the full URL)',
    '   - **Value / Points to:** `leasesmart2.netlify.app`',
    '   - **TTL:** 1 hour (or default)',
    '3. Remove conflicting **A** records for the same `leasesmart` host if any exist.',
    '',
    '## Step 2 — Netlify custom domain',
    '',
    '1. In Netlify → your LeaseSmart site → **Domain management**.',
    '2. Add `leasesmart.tgttechnologies.com` as a custom domain.',
    '3. Let Netlify provision the TLS certificate, then enable **Force HTTPS**.',
    '4. `_redirects` in the repo root keeps SPA routes working on Netlify.',
    '',
    '## Step 3 — Repo CNAME file',
    '',
    'The repo root `CNAME` file contains:',
    '',
    '```',
    'leasesmart.tgttechnologies.com',
    '```',
    '',
    'That file is read by **GitHub Pages** for its custom-domain setting. Leave it in place',
    'only while the Pages deploy is intentionally kept as a mirror. If GitHub Pages is ever',
    'retired, delete `CNAME` so Pages stops claiming the same hostname.',
    '',
    '## Step 4 — Expected propagation time',
    '',
    '- **DNS:** 15 minutes to 48 hours (often under 1 hour).',
    '- **Netlify certificate:** usually minutes after DNS resolves correctly.',
    '- Use [https://dnschecker.org](https://dnschecker.org) for `leasesmart.tgttechnologies.com` CNAME lookup.',
    '',
    '## Step 5 — Verify it worked',
    '',
    '1. Run `dig leasesmart.tgttechnologies.com CNAME +short` — expect `leasesmart2.netlify.app`.',
    '2. Run `curl -sI https://leasesmart.tgttechnologies.com | grep -i server` — expect `Netlify`.',
    '3. Confirm the deployed build matches the repo:',
    '',
    '```bash',
    'curl -s https://leasesmart.tgttechnologies.com | grep -o "LS_BUILD = \'[^\']*\'"',
    'grep -o "LS_BUILD = \'[^\']*\'" index.html',
    '```',
    '',
    '4. Hard-refresh or open a private window to avoid stale DNS and CDN cache.',
    '',
    '## Troubleshooting',
    '',
    '- **Old build still served:** Netlify cache or build not finished. Check the Netlify deploy log; a passing GitHub Pages run does not update the custom domain.',
    '- **Certificate pending:** Wait for Netlify to issue TLS; do not disable HTTPS enforcement prematurely.',
    '- **Wrong site or parking page:** CNAME points at the wrong target, or a stale `A` record still exists for `leasesmart`.',
    '- **Routes 404 on refresh:** `_redirects` missing from the deployed root.',
    '',
    '## Security notes',
    '',
    '- Never commit API keys, VAPID keys, or Supabase service role keys.',
    '- Beta/demo builds only until legal and billing sprints are attorney-approved.',
    '',
  ].join('\n');
}

export function writeDomainSetupGuide() {
  mkdirSync(join(ROOT, 'master-vault'), { recursive: true });
  const body = buildDomainSetupGuide();
  writeFileSync(DOMAIN_GUIDE_PATH, body + '\n', 'utf8');
  return { path: DOMAIN_GUIDE_PATH, lines: body.split('\n').length };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const r = writeDomainSetupGuide();
  console.log(JSON.stringify({ ok: true, ...r }, null, 2));
}
